import numpy as np
from scipy.optimize import minimize

def objective(x):
    a, b, c = x
    return (a*b - c**2) * (b*c - a**2) * (c*a - b**2)

def constraint(x):
    return x[0]**2 + x[1]**2 + x[2]**2 - 3

# Try to find the minimum value using multiple starts
min_val = float('inf')
for _ in range(50):
    x0 = np.random.uniform(-2, 2, 3)
    x0 = x0 * np.sqrt(3 / np.sum(x0**2))
    res = minimize(objective, x0, constraints={'type': 'eq', 'fun': constraint})
    if res.success and res.fun < min_val:
        min_val = res.fun

print(f"Minimum value found: {min_val}")

import numpy as np
from scipy.optimize import minimize

def get_p_max(S):
    k = (S**2 - 3) / 2
    # 27p^2 + (4S^3 - 18Sk)p + (4k^3 - S^2k^2) = 0
    a_coeff = 27
    b_coeff = 4*S**3 - 18*S*k
    c_coeff = 4*k**3 - S**2*k**2

    discriminant = b_coeff**2 - 4*a_coeff*c_coeff
    if discriminant < 0:
        return None

    p1 = (-b_coeff + np.sqrt(discriminant)) / (2 * a_coeff)
    p2 = (-b_coeff - np.sqrt(discriminant)) / (2 * a_coeff)
    return max(p1, p2)

def objective(S):
    k = (S**2 - 3) / 2
    p_max = get_p_max(S)
    if p_max is None:
        return float('inf')
    return k**3 - (p_max * S**3)

# Search for S in [-3, 3]
s_vals = np.linspace(-3, 3, 1000)
results = []
for s in s_vals:
    val = objective(s)
    if val != float('inf'):
        results.append((s, val))

min_s, min_val = min(results, key=lambda x: x[1])
print(f"Min value: {min_val} at S: {min_s}")
